set.seed(123);.libPaths(c('.Rlib',.libPaths()));suppressPackageStartupMessages({library(data.table);library(survival)})
d=readRDS('data/revision_R1/METABRIC_analysis.rds');d=d[complete.cases(d[,.(time,event,age,original,immune)]) & time>0];d[,score:=original]
m=coxph(Surv(time,event)~score+age+tt(score),data=d,tt=function(x,t,...)x*log(pmax(t,1)/365.25));b=coef(m)[c('score','tt(score)')];v=vcov(m)[names(b),names(b)];a=rbindlist(lapply(c(1,3,5,10),function(yr){w=c(1,log(yr));beta=sum(w*b);se=sqrt(drop(t(w)%*%v%*%w));data.table(dataset='METABRIC',subset='all_primary',years=yr,n=nrow(d),events=sum(d$event),hr=exp(beta),lower=exp(beta-1.96*se),upper=exp(beta+1.96*se))}));fwrite(a,'results/revision_R1/tables/METABRIC_time_varying_HR.csv');writeLines(capture.output(sessionInfo()),'logs/revision_R1/time_effect_sessionInfo.txt');print(a)
